    LANGUAGE_WRAPPER = 'Consider an equilateral triangle whose sides are divided into {m} equal parts. Through each division point, draw lines parallel to the other two sides. Together with the sides of the triangle, these parallels define a triangular lattice of {num_points} points. An axial isosceles triangle is defined as a triangle whose two equal sides are parallel to two distinct sides of the original equilateral triangle (i.e., the equal legs align with two of the three lattice directions). Determine T({m}), the total number of axial isosceles triangles whose vertices lie among these lattice points. After solving the above problem, please output your final answer in the following format:\n### The final answer is: $\\boxed{<your answer>}$\nExample:\n### The final answer is: $\\boxed{123}$\nThe final answer should be given as precisely as possible (using LaTeX symbols such as \\sqrt, \\frac, \\pi, etc.). If the final answer involves a decimal approximation, it must be accurate to at least four decimal places.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# choose m moderately large to ensure non-trivial counting
m = rng.randint(4, 60)
num_points = (m + 1) * (m + 2) // 2
return {'m': m, 'num_points': num_points}

    def verifier(assign):
# Validate input
if not isinstance(assign, dict):
    # invalid assignment
    return (False, None)
if 'm' not in assign or 'num_points' not in assign:
    # missing keys
    return (False, None)
m = assign['m']
num_points = assign['num_points']
if not isinstance(m, int) or not isinstance(num_points, int):
    return (False, None)
if m < 4:
    # enforce non-trivial instances
    return (False, None)
# recompute num_points and verify consistency
np_calc = (m + 1) * (m + 2) // 2
if np_calc != num_points:
    return (False, None)
# Count oriented axial isosceles triangles toward a fixed vertex (say toward vertex C):
# As derived in the proof notes, for each row index k=1..m (distance from AB-side),
# row length L = m - k + 1, and allowable base separations s = 1..min(k, L-1).
# Each valid separation contributes (L - s) triangles. Sum over k and s, then multiply by 3 orientations.
T_oriented = 0
for k in range(1, m + 1):
    L = m - k + 1
    u = min(k, L - 1)
    if u > 0:
        # sum_{s=1}^u (L - s) = u*L - u(u+1)/2
        T_oriented += u * L - (u * (u + 1)) // 2
T_total = 3 * T_oriented
# Additionally, cross-check with closed-form piecewise formulas to ensure robustness
# Even m = 2q: T_total = q(q+1)(4q - 1)/2
# Odd  m = 2q+1: T_total = q(q+1)(4q + 5)/2
if m % 2 == 0:
    q = m // 2
    T_closed = q * (q + 1) * (4 * q - 1) // 2
else:
    q = (m - 1) // 2
    T_closed = q * (q + 1) * (4 * q + 5) // 2
# The two computations must agree; if not, flag invalid
if T_total != T_closed:
    return (False, None)
answer = f"### The final answer is: $\\boxed{{{T_total}}}$"
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

